#!/usr/bin/env node
/**
 * Frontend contract conformance (pack 01 doc 08 — contracts cannot silently
 * drift from the canonical backend). Validates that the frontend's hand-declared
 * DTOs in apps/web/src/lib/api.ts DECLARE every field the canonical backend
 * actually returns, per contracts/public-api.contract.json (generated by the
 * backend from its live responses and copied here verbatim).
 *
 * Direction: contract fields ⊆ frontend DTO fields. If the backend adds or
 * renames a field the frontend hasn't picked up, this fails — so drift is caught
 * in CI instead of surfacing as a silent `undefined` at runtime. Extra optional
 * frontend fields are allowed.
 *
 * Keep contracts/public-api.contract.json in sync with the backend: regenerate
 * there with `pnpm run contract:emit` and copy the file across.
 */
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const contract = JSON.parse(readFileSync(join(root, 'contracts/public-api.contract.json'), 'utf8'));
const api = readFileSync(join(root, 'apps/web/src/lib/api.ts'), 'utf8');

// endpoint → { interface, pick } where `pick` narrows the contract node whose
// fields the interface must cover (e.g. the list envelope's item shape).
const MAP = {
  'GET /api/v2/catalogue': { iface: 'CatalogueCardV2', node: (s) => s.items[0] },
  'GET /api/v2/catalogue/row': { iface: 'CatalogueRowResponse', node: (s) => s },
  'GET /auctions/:id/state': { iface: 'AuctionState', node: (s) => s },
  'GET /api/v2/me/dashboard': { iface: 'DashboardProjection', node: (s) => s },
};

/** Top-level field names declared by `export interface Name { ... }` in api.ts. */
function interfaceFields(name) {
  const start = api.search(new RegExp(`export interface ${name}\\b[^{]*{`));
  if (start === -1) throw new Error(`interface ${name} not found in api.ts`);
  let i = api.indexOf('{', start);
  let depth = 0;
  const fields = new Set();
  let atTopOfMember = true;
  for (; i < api.length; i += 1) {
    const ch = api[i];
    if (ch === '{') {
      depth += 1;
      continue;
    }
    if (ch === '}') {
      depth -= 1;
      if (depth === 0) break;
      continue;
    }
    if (depth === 1) {
      if (ch === '\n' || ch === ';') {
        atTopOfMember = true;
        continue;
      }
      if (atTopOfMember && /\s/.test(ch)) continue;
      if (atTopOfMember) {
        // Capture the identifier at the start of a member line.
        const m = api.slice(i).match(/^([a-zA-Z_$][\w$]*)\s*\??\s*:/);
        if (m) fields.add(m[1]);
        atTopOfMember = false;
      }
    }
  }
  return fields;
}

let failed = 0;
for (const [endpoint, { iface, node }] of Object.entries(MAP)) {
  const shape = node(contract.endpoints[endpoint]);
  const contractFields = Object.keys(shape);
  const declared = interfaceFields(iface);
  const missing = contractFields.filter((f) => !declared.has(f));
  if (missing.length) {
    console.error(`  ✗ ${endpoint} → ${iface}: missing field(s) [${missing.join(', ')}]`);
    failed += 1;
  } else {
    console.log(`  ✓ ${endpoint} → ${iface} (${contractFields.length} fields covered)`);
  }
}

if (failed) {
  console.error(
    `\n${failed} contract mismatch(es). The backend returns fields the frontend DTO does not declare — sync api.ts (and re-copy contracts/public-api.contract.json).`,
  );
  process.exit(1);
}
console.log('\nFrontend DTOs cover the canonical backend contract — no silent drift.');
